1	import { useQuery } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	import { useAuth } from "@/hooks/useAuth";
4	
5	type TeamRole = "owner" | "admin" | "member";
6	
7	export interface TeamMember {
8	  id: string;
9	  user_id: string;
10	  role: TeamRole;
11	  joined_at: string;
12	  email?: string;
13	}
14	
15	export interface TeamInvitation {
16	  id: string;
17	  email: string;
18	  role: TeamRole;
19	  status: string;
20	  created_at: string;
21	  expires_at: string;
22	}
23	
24	export interface Team {
25	  id: string;
26	  name: string;
27	  owner_id: string;
28	}
29	
30	export function useTeam() {
31	  const { user } = useAuth();
32	  const userId = user?.id;
33	
34	  const { data, isLoading, refetch } = useQuery({
35	    queryKey: ["team", userId],
36	    queryFn: async () => {
37	      if (!userId) return { team: null, members: [], invitations: [], myRole: null };
38	
39	      // Get user's owned team
40	      const { data: tmData } = await (supabase as any)
41	        .from("team_members")
42	        .select("team_id, role")
43	        .eq("user_id", userId)
44	        .eq("role", "owner")
45	        .limit(1)
46	        .maybeSingle();
47	
48	      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };
49	
50	      const teamId = tmData.team_id;
51	
52	      // Fetch team, members, invitations in parallel
53	      const [teamRes, membersRes, invitationsRes] = await Promise.all([
54	        (supabase as any).from("teams").select("id, name, owner_id").eq("id", teamId).single(),
55	        (supabase as any).from("team_members").select("id, user_id, role, joined_at").eq("team_id", teamId).order("joined_at"),
56	        (supabase as any).from("team_invitations").select("id, email, role, status, created_at, expires_at").eq("team_id", teamId).eq("status", "pending").order("created_at", { ascending: false }),
57	      ]);
58	
59	      const team: Team | null = teamRes.data ?? null;
60	      const rawMembers = (membersRes.data ?? []) as TeamMember[];
61	      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];
62	
63	      // Augment current user's own record with their email; others show user_id until
64	      // a profiles.email column is available.
65	      const members = rawMembers.map((m) => ({
66	        ...m,
67	        email: m.user_id === userId ? user?.email ?? undefined : undefined,
68	      }));
69	
70	      return { team, members, invitations, myRole: tmData.role as TeamRole };
71	    },
72	    enabled: !!userId,
73	    staleTime: 60_000,
74	  });
75	
76	  return {
77	    team: data?.team ?? null,
78	    members: data?.members ?? [],
79	    invitations: data?.invitations ?? [],
80	    myRole: data?.myRole ?? null,
81	    isLoading,
82	    refetch,
83	  };
84	}
