48	import { useTeam, type TeamMember, type TeamInvitation } from "@/hooks/useTeam";
49	import { supabase } from "@/integrations/supabase/client";
50	import { useAuth } from "@/hooks/useAuth";
51	
52	type TeamRole = "owner" | "admin" | "member";
53	
54	const ROLE_LABELS: Record<TeamRole, string> = {
55	  owner: "Owner",
56	  admin: "Admin",
57	  member: "Member",
58	};
59	
60	const ROLE_VARIANTS: Record<TeamRole, "default" | "secondary" | "outline"> = {
61	  owner: "default",
62	  admin: "secondary",
63	  member: "outline",
64	};
65	
66	function RoleBadge({ role }: { role: TeamRole }) {
67	  const Icon = role === "owner" ? Crown : role === "admin" ? Shield : Users;
68	  return (
69	    <Badge variant={ROLE_VARIANTS[role]} className="gap-1 text-xs font-medium">
70	      <Icon className="h-3 w-3" />
71	      {ROLE_LABELS[role]}
72	    </Badge>
73	  );
74	}
75	
76	function MembersSkeleton() {
77	  return (
78	    <div className="space-y-3">
79	      {[1, 2, 3].map((i) => (
80	        <div key={i} className="flex items-center gap-4 px-4 py-3">
81	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
82	          <div className="flex-1 space-y-1.5">
83	            <Skeleton className="h-4 w-48" />
84	            <Skeleton className="h-3 w-32" />
85	          </div>
86	          <Skeleton className="h-6 w-16 rounded-full" />
87	          <Skeleton className="h-8 w-8 rounded" />
88	        </div>
89	      ))}
90	    </div>
91	  );
92	}
93	
94	const Team = () => {
95	  const { user } = useAuth();
96	  const { team, members, invitations, myRole, isLoading, refetch } = useTeam();
97	
98	  const [inviteEmail, setInviteEmail] = useState("");
99	  const [inviteRole, setInviteRole] = useState<"admin" | "member">("member");
100	  const [isSendingInvite, setIsSendingInvite] = useState(false);
101	  const [revokingId, setRevokingId] = useState<string | null>(null);
102	  const [removingId, setRemovingId] = useState<string | null>(null);
103	  const [updatingRoleId, setUpdatingRoleId] = useState<string | null>(null);
104	
105	  // Show management controls if user is owner/admin, or if team hasn't loaded yet
106	  // (owner sees their own team — default to showing controls)
107	  const canManage = myRole === "owner" || myRole === "admin" || (!isLoading && !team);
108	
109	  async function handleInvite(e: React.FormEvent) {
110	    e.preventDefault();
111	    if (!inviteEmail.trim()) return;
112	
113	    setIsSendingInvite(true);
114	    try {
115	      const { error } = await (supabase as any)
116	        .from("team_invitations")
117	        .insert({
118	          team_id: team?.id,
119	          email: inviteEmail.trim().toLowerCase(),
120	          role: inviteRole,
121	          invited_by: user?.id,
122	          status: "pending",
123	          expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
124	        });
125	
126	      if (error) throw error;
127	
128	      toast.success(`Invitation sent to ${inviteEmail.trim()}`);
129	      setInviteEmail("");
130	      refetch();
131	    } catch (err: unknown) {
132	      const msg = err instanceof Error ? err.message : "Failed to send invitation";
133	      toast.error(msg);
134	    } finally {
135	      setIsSendingInvite(false);
136	    }
137	  }
138	
139	  async function handleRevokeInvite(id: string, email: string) {
140	    setRevokingId(id);
141	    try {
142	      const { error } = await (supabase as any)
143	        .from("team_invitations")
144	        .update({ status: "revoked" })
145	        .eq("id", id);
146	
147	      if (error) throw error;
148	
149	      toast.success(`Invitation to ${email} revoked`);
150	      refetch();
151	    } catch (err: unknown) {
152	      toast.error("Failed to revoke invitation");
153	    } finally {
154	      setRevokingId(null);
155	    }
156	  }
157	
158	  async function handleChangeRole(member: TeamMember, newRole: TeamRole) {
159	    if (newRole === member.role) return;
160	    setUpdatingRoleId(member.id);
161	    try {
162	      const { error } = await (supabase as any)
163	        .from("team_members")
164	        .update({ role: newRole })
165	        .eq("id", member.id);
166	
167	      if (error) throw error;
168	
169	      toast.success(`Role updated to ${ROLE_LABELS[newRole]}`);
170	      refetch();
171	    } catch (err: unknown) {
172	      toast.error("Failed to update role");
173	    } finally {
174	      setUpdatingRoleId(null);
175	    }
176	  }
177	
178	  async function handleRemoveMember(member: TeamMember) {
179	    setRemovingId(member.id);
180	    try {
181	      const { error } = await (supabase as any)
182	        .from("team_members")
183	        .delete()
184	        .eq("id", member.id);
185	
186	      if (error) throw error;
187	
188	      toast.success("Member removed from team");
189	      refetch();
190	    } catch (err: unknown) {
191	      toast.error("Failed to remove member");
192	    } finally {
193	      setRemovingId(null);
194	    }
195	  }
196	
197	  const pendingInvitations = invitations.filter((inv) => inv.status === "pending");
198	  const nonOwnerMembers = members.filter((m) => m.role !== "owner");
199	
200	  return (
201	    <SidebarLayout>
202	      <main className="w-full max-w-[760px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
203	        <FadeIn>
204	          <div className="flex items-center justify-between mb-1">
205	            <h1 className="text-xl font-semibold text-foreground tracking-tight">Team</h1>
206	            {team && (
207	              <span className="text-sm text-muted-foreground">{team.name}</span>
208	            )}
209	          </div>
210	          <p className="text-sm text-muted-foreground mb-6">
211	            Manage your team members and pending invitations.
212	          </p>
213	        </FadeIn>
214	
215	        <StaggerList className="space-y-6" stagger={0.08}>
216	          {/* Invite card — only visible to owners/admins */}
217	          {canManage && (
218	            <Card>
219	              <CardHeader className="pb-3">
220	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
221	                  <UserPlus className="h-4 w-4 text-primary" />
222	                  Invite a teammate
223	                </CardTitle>
224	              </CardHeader>
225	              <CardContent>
226	                <form onSubmit={handleInvite} className="flex flex-col sm:flex-row gap-2">
227	                  <div className="relative flex-1">
228	                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
229	                    <Input
230	                      type="email"
231	                      placeholder="colleague@company.com"
232	                      value={inviteEmail}
233	                      onChange={(e) => setInviteEmail(e.target.value)}
234	                      className="pl-9"
235	                      required
236	                      disabled={isSendingInvite}
237	                    />
238	                  </div>
239	                  <Select
240	                    value={inviteRole}
241	                    onValueChange={(v) => setInviteRole(v as "admin" | "member")}
242	                    disabled={isSendingInvite}
243	                  >
244	                    <SelectTrigger className="w-full sm:w-32">
245	                      <SelectValue />
246	                    </SelectTrigger>
247	                    <SelectContent>
248	                      <SelectItem value="member">Member</SelectItem>
249	                      <SelectItem value="admin">Admin</SelectItem>
250	                    </SelectContent>
251	                  </Select>
252	                  <Button
253	                    type="submit"
254	                    disabled={isSendingInvite || !inviteEmail.trim()}
255	                    className="gap-1.5 shrink-0"
256	                  >
257	                    {isSendingInvite ? (
258	                      <Loader2 className="h-4 w-4 animate-spin" />
259	                    ) : (
260	                      <UserPlus className="h-4 w-4" />
261	                    )}
262	                    Send invite
263	                  </Button>
264	                </form>
265	              </CardContent>
266	            </Card>
267	          )}
268	
269	          {/* Pending invitations */}
270	          {(pendingInvitations.length > 0 || (isLoading && canManage)) && (
271	            <Card>
272	              <CardHeader className="pb-3">
273	                <div className="flex items-center justify-between">
274	                  <CardTitle className="text-sm font-semibold flex items-center gap-2">
275	                    <Mail className="h-4 w-4 text-primary" />
276	                    Pending invitations
277	                    {!isLoading && (
278	                      <Badge variant="secondary" className="ml-1 text-xs">
279	                        {pendingInvitations.length}
280	                      </Badge>
281	                    )}
282	                  </CardTitle>
283	                  <Button
284	                    variant="ghost"
285	                    size="icon"
286	                    className="h-7 w-7"
287	                    onClick={() => refetch()}
288	                    disabled={isLoading}
289	                    aria-label="Refresh invitations"
290	                  >
291	                    <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
292	                  </Button>
293	                </div>
294	              </CardHeader>
295	              <CardContent className="p-0">
296	                {isLoading ? (
297	                  <div className="space-y-2 p-4">
298	                    {[1, 2].map((i) => (
299	                      <Skeleton key={i} className="h-10 w-full rounded-md" />
300	                    ))}
301	                  </div>
302	                ) : (
303	                  <Table>
304	                    <TableHeader>
305	                      <TableRow>
306	                        <TableHead className="text-xs">Email</TableHead>
307	                        <TableHead className="text-xs">Role</TableHead>
308	                        <TableHead className="text-xs">Expires</TableHead>
309	                        {canManage && <TableHead className="text-xs w-16" />}
310	                      </TableRow>
311	                    </TableHeader>
312	                    <TableBody>
313	                      {pendingInvitations.map((inv: TeamInvitation) => (
314	                        <TableRow key={inv.id}>
315	                          <TableCell className="text-sm font-medium">{inv.email}</TableCell>
316	                          <TableCell>
317	                            <RoleBadge role={inv.role} />
318	                          </TableCell>
319	                          <TableCell className="text-xs text-muted-foreground">
320	                            {format(new Date(inv.expires_at), "MMM d, yyyy")}
321	                          </TableCell>
322	                          {canManage && (
323	                            <TableCell>
324	                              <Button
325	                                variant="ghost"
326	                                size="icon"
327	                                className="h-7 w-7 text-muted-foreground hover:text-destructive"
328	                                onClick={() => handleRevokeInvite(inv.id, inv.email)}
329	                                disabled={revokingId === inv.id}
330	                                aria-label={`Revoke invite for ${inv.email}`}
331	                              >
332	                                {revokingId === inv.id ? (
333	                                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
334	                                ) : (
335	                                  <Trash2 className="h-3.5 w-3.5" />
336	                                )}
337	                              </Button>
338	                            </TableCell>
339	                          )}
340	                        </TableRow>
341	                      ))}
342	                    </TableBody>
343	                  </Table>
344	                )}
345	              </CardContent>
346	            </Card>
347	          )}
348	
349	          {/* Members table */}
350	          <Card>
351	            <CardHeader className="pb-3">
352	              <div className="flex items-center justify-between">
353	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
354	                  <Users className="h-4 w-4 text-primary" />
355	                  Members
356	                  {!isLoading && (
357	                    <Badge variant="secondary" className="ml-1 text-xs">
358	                      {members.length}
359	                    </Badge>
360	                  )}
361	                </CardTitle>
362	                <Button
363	                  variant="ghost"
364	                  size="icon"
365	                  className="h-7 w-7"
366	                  onClick={() => refetch()}
367	                  disabled={isLoading}
368	                  aria-label="Refresh members"
369	                >
370	                  <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
371	                </Button>
372	              </div>
373	            </CardHeader>
374	            <CardContent className="p-0">
375	              {isLoading ? (
376	                <MembersSkeleton />
377	              ) : members.length === 0 ? (
378	                <div className="flex flex-col items-center justify-center py-12 space-y-3 text-center px-4">
379	                  <div className="rounded-xl bg-muted/50 p-4">
380	                    <Users className="h-7 w-7 text-muted-foreground/50" />
381	                  </div>
382	                  <div className="space-y-1">
383	                    <p className="text-sm font-medium text-foreground">No team yet</p>
384	                    <p className="text-sm text-muted-foreground max-w-xs">
385	                      Invite a colleague above to start collaborating on job rankings.
386	                    </p>
387	                  </div>
388	                </div>
389	              ) : (
390	                <Table>
391	                  <TableHeader>
392	                    <TableRow>
393	                      <TableHead className="text-xs">Member</TableHead>
394	                      <TableHead className="text-xs">Role</TableHead>
395	                      <TableHead className="text-xs">Joined</TableHead>
396	                      {canManage && <TableHead className="text-xs w-12" />}
397	                    </TableRow>
398	                  </TableHeader>
399	                  <TableBody>
400	                    {members.map((member: TeamMember) => {
401	                      const isCurrentUser = member.user_id === user?.id;
402	                      const isOwner = member.role === "owner";
403	                      return (
404	                        <TableRow key={member.id}>
405	                          <TableCell>
406	                            <div className="flex flex-col">
407	                              <span className="text-sm font-medium">
408	                                {member.email ?? member.user_id.slice(0, 8) + "…"}
409	                                {isCurrentUser && (
410	                                  <span className="ml-1.5 text-xs text-muted-foreground font-normal">(you)</span>
411	                                )}
412	                              </span>
413	                            </div>
414	                          </TableCell>
415	                          <TableCell>
416	                            {canManage && !isOwner && !isCurrentUser ? (
417	                              <Select
418	                                value={member.role}
419	                                onValueChange={(v) => handleChangeRole(member, v as TeamRole)}
420	                                disabled={updatingRoleId === member.id}
421	                              >
422	                                <SelectTrigger className="h-7 w-28 text-xs border-0 bg-transparent px-0 focus:ring-0 focus:ring-offset-0">
423	                                  <SelectValue />
424	                                </SelectTrigger>
425	                                <SelectContent>
426	                                  <SelectItem value="admin">Admin</SelectItem>
427	                                  <SelectItem value="member">Member</SelectItem>
428	                                </SelectContent>
429	                              </Select>
430	                            ) : (
431	                              <RoleBadge role={member.role} />
432	                            )}
433	                          </TableCell>
434	                          <TableCell className="text-xs text-muted-foreground">
435	                            {format(new Date(member.joined_at), "MMM d, yyyy")}
436	                          </TableCell>
437	                          {canManage && (
438	                            <TableCell>
439	                              {!isOwner && !isCurrentUser && (
440	                                <AlertDialog>
441	                                  <AlertDialogTrigger asChild>
442	                                    <Button
443	                                      variant="ghost"
444	                                      size="icon"
445	                                      className="h-7 w-7 text-muted-foreground hover:text-destructive"
446	                                      disabled={removingId === member.id}
447	                                      aria-label={`Remove ${member.email ?? "member"}`}
448	                                    >
449	                                      {removingId === member.id ? (
450	                                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
451	                                      ) : (
452	                                        <Trash2 className="h-3.5 w-3.5" />
453	                                      )}
454	                                    </Button>
455	                                  </AlertDialogTrigger>
456	                                  <AlertDialogContent>
457	                                    <AlertDialogHeader>
458	                                      <AlertDialogTitle>Remove member?</AlertDialogTitle>
459	                                      <AlertDialogDescription>
460	                                        {member.email ?? "This member"} will lose access to the team immediately. This action cannot be undone.
461	                                      </AlertDialogDescription>
462	                                    </AlertDialogHeader>
463	                                    <AlertDialogFooter>
464	                                      <AlertDialogCancel>Cancel</AlertDialogCancel>
465	                                      <AlertDialogAction
466	                                        onClick={() => handleRemoveMember(member)}
467	                                        className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
468	                                      >
469	                                        Remove
470	                                      </AlertDialogAction>
471	                                    </AlertDialogFooter>
472	                                  </AlertDialogContent>
473	                                </AlertDialog>
474	                              )}
475	                            </TableCell>
476	                          )}
477	                        </TableRow>
478	                      );
479	                    })}
480	                  </TableBody>
481	                </Table>
482	              )}
483	            </CardContent>
484	          </Card>
485	        </StaggerList>
486	      </main>
487	    </SidebarLayout>
488	  );
489	};
490	
491	export default Team;
