1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
3	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
4	
5	// ── CORS ──────────────────────────────────────────────────────
6	const ALLOWED_ORIGINS = [
7	  Deno.env.get("APP_URL") || "https://rankora.co",
8	  "https://www.rankora.co",
9	  "http://localhost:8080",
10	  "http://localhost:5173",
11	];
12	
13	function getCorsOrigin(req: Request): string {
14	  const origin = req.headers.get("origin") || "";
15	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
16	}
17	
18	function corsHeaders(req: Request) {
19	  return {
20	    "Access-Control-Allow-Origin": getCorsOrigin(req),
21	    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
22	  };
23	}
24	
25	// ── Types ─────────────────────────────────────────────────────
26	interface InviteRequest {
27	  team_id: string;
28	  email: string;
29	  role: "admin" | "member";
30	}
31	
32	// ── Email HTML ────────────────────────────────────────────────
33	function buildInviteEmail(params: {
34	  inviterName: string;
35	  teamName: string;
36	  role: string;
37	  inviteLink: string;
38	}): { subject: string; html: string } {
39	  const subject = `${params.inviterName} invited you to join ${params.teamName} on Rankora`;
40	  const html = `<!DOCTYPE html>
41	<html lang="en">
42	<head>
43	  <meta charset="UTF-8" />
44	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
45	  <title>${subject}</title>
