1	export function extractLinkedInUrl(result: { parsed_json?: any; linkedin_url?: string }): string | null {
2	  if (result.linkedin_url) return normalizeLinkedInUrl(result.linkedin_url);
3	
4	  const pj = result.parsed_json;
5	  if (!pj) return null;
6	
7	  if (typeof pj.linkedin === "string" && pj.linkedin) return normalizeLinkedInUrl(pj.linkedin);
8	  if (typeof pj.linkedin_url === "string" && pj.linkedin_url) return normalizeLinkedInUrl(pj.linkedin_url);
9	  if (pj.contact?.linkedin) return normalizeLinkedInUrl(pj.contact.linkedin);
10	  if (pj.contact?.linkedin_url) return normalizeLinkedInUrl(pj.contact.linkedin_url);
11	  if (pj.links?.linkedin) return normalizeLinkedInUrl(pj.links.linkedin);
12	
13	  return null;
14	}
15	
16	function normalizeLinkedInUrl(url: string): string {
17	  const trimmed = url.trim();
18	  if (trimmed.startsWith("http")) return trimmed;
19	  if (trimmed.startsWith("linkedin.com") || trimmed.startsWith("www.linkedin.com")) return "https://" + trimmed;
20	  if (trimmed.startsWith("in/")) return "https://www.linkedin.com/" + trimmed;
21	  return "https://www.linkedin.com/in/" + trimmed;
22	}
